-- PostgreSQL state for environment zaowutai-d5gkmk1fh36dd0fda.
-- Install with the environment's administrative SQL interface, not a browser.
-- Bridge contract: POST RPC /ludoready_state with { op, input }.
-- After authenticating and validating the HTTP request, the Node bridge adds:
--   create: input.generated = { id, session, sessionHash, previewToken }
--   authorized/revise/claim: input.sessionHash = sha256(session), or null
--   claim-next: input.runId is generated by the authenticated Node bridge;
--               no project ID, revision or owner session is required.
-- IDs and random tokens are generated with node:crypto before the RPC call.
-- The raw session is returned on create only; the stored job contains its hash.
-- A result is a scalar JSON object { status, body }, translated by the HTTP bridge.
-- Every invocation is one transaction; no model or file operations occur here.

BEGIN;

CREATE TABLE IF NOT EXISTS public.ludoready_projects (
  id text PRIMARY KEY,
  job jsonb NOT NULL CHECK (jsonb_typeof(job) = 'object' AND job ->> 'id' = id)
);

CREATE TABLE IF NOT EXISTS public.ludoready_usage (
  day text PRIMARY KEY,
  count integer NOT NULL CHECK (count BETWEEN 0 AND 20)
);

ALTER TABLE public.ludoready_projects ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ludoready_projects FORCE ROW LEVEL SECURITY;
ALTER TABLE public.ludoready_usage ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.ludoready_usage FORCE ROW LEVEL SECURITY;
REVOKE ALL ON public.ludoready_projects, public.ludoready_usage FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE ON public.ludoready_projects, public.ludoready_usage TO service_role;
-- No client RLS policies. CloudBase service_role has BYPASSRLS.

CREATE OR REPLACE FUNCTION public.ludoready_state(op text, input jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, public
AS $ludoready$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_time text := to_char(v_now AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
  v_day text := to_char(v_now AT TIME ZONE 'Asia/Shanghai', 'YYYY-MM-DD');
  v_id text;
  v_prompt text;
  v_generated jsonb;
  v_session text;
  v_job jsonb;
  v_revision integer;
  v_requested_revision numeric;
  v_has_published boolean;
  v_revisions jsonb;
  v_revision_index integer;
  v_events jsonb;
  v_count integer;
  v_status text;
  v_stage text;
  v_message text;
  v_error jsonb;
  v_started timestamptz;
  v_publication jsonb;
  v_files jsonb := '[]'::jsonb;
  v_parts jsonb := '[]'::jsonb;
  v_file jsonb;
  v_size numeric;
  v_field text;
BEGIN
  -- CloudBase's RPC gateway currently does not enforce function EXECUTE grants.
  -- Check JWT role as well as table grants/RLS. NULL claims must be denied.
  IF (COALESCE(NULLIF(current_setting('request.jwt.claims', true), ''), '{}')::jsonb ->> 'role')
      IS DISTINCT FROM 'service_role' THEN
    RETURN jsonb_build_object('status', 403, 'body', jsonb_build_object('error', '状态服务请求未获授权。'));
  END IF;
  IF op IS NULL OR op NOT IN ('create', 'get', 'authorized', 'preview', 'revise', 'claim', 'claim-next', 'update') THEN
    RETURN jsonb_build_object('status', 400, 'body', jsonb_build_object('error', '请求操作无效。'));
  END IF;
  IF jsonb_typeof(input) IS DISTINCT FROM 'object' THEN
    RETURN jsonb_build_object('status', 400, 'body', jsonb_build_object('error', '请求格式无效。'));
  END IF;

  IF op IN ('create', 'revise') THEN
    v_prompt := CASE WHEN jsonb_typeof(input -> 'prompt') = 'string' THEN btrim(input ->> 'prompt', E' \t\n\r') ELSE '' END;
    IF v_prompt = '' OR char_length(v_prompt) > 1000 THEN
      RETURN jsonb_build_object('status', 400, 'body', jsonb_build_object('error',
        CASE WHEN op = 'create' THEN '请填写 1–1000 字的游戏想法。' ELSE '请填写 1–1000 字的修改要求。' END));
    END IF;
  END IF;
  IF op NOT IN ('create', 'claim-next') THEN
    v_id := input ->> 'id';
    IF jsonb_typeof(input -> 'id') IS DISTINCT FROM 'string'
        OR v_id !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' THEN
      RETURN jsonb_build_object('status', 400, 'body', jsonb_build_object('error', '项目编号无效。'));
    END IF;
  END IF;
  IF op IN ('claim', 'update') THEN
    IF jsonb_typeof(input -> 'revision') IS DISTINCT FROM 'number' THEN
      RETURN jsonb_build_object('status', 400, 'body', jsonb_build_object('error', '项目版本无效。'));
    END IF;
    v_requested_revision := (input ->> 'revision')::numeric;
    IF v_requested_revision < 0 OR v_requested_revision <> trunc(v_requested_revision) THEN
      RETURN jsonb_build_object('status', 400, 'body', jsonb_build_object('error', '项目版本无效。'));
    END IF;
  END IF;
  IF op IN ('claim', 'claim-next', 'update') AND (jsonb_typeof(input -> 'runId') IS DISTINCT FROM 'string'
      OR (input ->> 'runId') !~ '^[A-Za-z0-9_-]{16,128}$') THEN
    RETURN jsonb_build_object('status', 400, 'body', jsonb_build_object('error', '制作任务标识无效。'));
  END IF;
  IF op = 'update' THEN
    IF jsonb_typeof(input -> 'status') IS DISTINCT FROM 'string' OR (input ->> 'status') NOT IN ('running', 'complete', 'failed')
        OR jsonb_typeof(input -> 'stage') IS DISTINCT FROM 'string' OR char_length(input ->> 'stage') NOT BETWEEN 1 AND 80
        OR jsonb_typeof(input -> 'message') IS DISTINCT FROM 'string' OR char_length(input ->> 'message') > 4000
        OR (input -> 'error' IS NOT NULL AND input -> 'error' <> 'null'::jsonb AND jsonb_typeof(input -> 'error') <> 'string') THEN
      RETURN jsonb_build_object('status', 400, 'body', jsonb_build_object('error', '制作进度格式无效。'));
    END IF;
    IF input ? 'draftSourceKey' AND (jsonb_typeof(input -> 'draftSourceKey') IS DISTINCT FROM 'string'
        OR char_length(input ->> 'draftSourceKey') NOT BETWEEN 1 AND 1000) THEN
      RETURN jsonb_build_object('status', 400, 'body', jsonb_build_object('error', '制作草稿标识无效。'));
    END IF;
    IF input ->> 'status' = 'complete' THEN
      v_publication := input -> 'publication';
      IF jsonb_typeof(v_publication) IS DISTINCT FROM 'object'
          OR jsonb_typeof(v_publication -> 'files') IS DISTINCT FROM 'array'
          OR jsonb_typeof(v_publication -> 'archiveKeys') IS DISTINCT FROM 'array'
          OR jsonb_typeof(v_publication -> 'sourceKey') IS DISTINCT FROM 'string'
          OR char_length(v_publication ->> 'sourceKey') NOT BETWEEN 1 AND 1000 THEN
        RETURN jsonb_build_object('status', 400, 'body', jsonb_build_object('error', '已发布游戏的文件清单无效。'));
      END IF;
      IF jsonb_array_length(v_publication -> 'files') NOT BETWEEN 1 AND 80 OR jsonb_array_length(v_publication -> 'archiveKeys') < 1 THEN
        RETURN jsonb_build_object('status', 400, 'body', jsonb_build_object('error', '已发布游戏的文件清单无效。'));
      END IF;
      FOR v_file IN SELECT value FROM jsonb_array_elements(v_publication -> 'files') LOOP
        FOREACH v_field IN ARRAY ARRAY['path', 'key', 'type'] LOOP
          IF jsonb_typeof(v_file -> v_field) IS DISTINCT FROM 'string' OR char_length(v_file ->> v_field) NOT BETWEEN 1 AND 1000 THEN
            RETURN jsonb_build_object('status', 400, 'body', jsonb_build_object('error', '已发布游戏的文件清单无效。'));
          END IF;
        END LOOP;
        IF left(v_file ->> 'path', 1) = '/' OR (v_file ->> 'path') ~ '(^|/)\.\.?(/|$)'
            OR jsonb_typeof(v_file -> 'size') IS DISTINCT FROM 'number' THEN
          RETURN jsonb_build_object('status', 400, 'body', jsonb_build_object('error', '已发布游戏的文件清单无效。'));
        END IF;
        v_size := (v_file ->> 'size')::numeric;
        IF v_size < 0 OR v_size > 9007199254740991 OR v_size <> trunc(v_size) THEN
          RETURN jsonb_build_object('status', 400, 'body', jsonb_build_object('error', '已发布游戏的文件清单无效。'));
        END IF;
        v_files := v_files || jsonb_build_array(jsonb_build_object('path', v_file -> 'path', 'key', v_file -> 'key', 'size', v_file -> 'size', 'type', v_file -> 'type'));
      END LOOP;
      FOR v_file IN SELECT value FROM jsonb_array_elements(v_publication -> 'archiveKeys') LOOP
        IF jsonb_typeof(v_file -> 'key') IS DISTINCT FROM 'string' OR char_length(v_file ->> 'key') NOT BETWEEN 1 AND 1000
            OR jsonb_typeof(v_file -> 'size') IS DISTINCT FROM 'number' THEN
          RETURN jsonb_build_object('status', 400, 'body', jsonb_build_object('error', '已发布游戏的文件清单无效。'));
        END IF;
        v_size := (v_file ->> 'size')::numeric;
        IF v_size < 0 OR v_size > 9007199254740991 OR v_size <> trunc(v_size) THEN
          RETURN jsonb_build_object('status', 400, 'body', jsonb_build_object('error', '已发布游戏的文件清单无效。'));
        END IF;
        v_parts := v_parts || jsonb_build_array(jsonb_build_object('key', v_file -> 'key', 'size', v_file -> 'size'));
      END LOOP;
      v_publication := jsonb_build_object('files', v_files, 'archiveKeys', v_parts, 'sourceKey', v_publication -> 'sourceKey');
    END IF;
  END IF;

  IF op = 'create' THEN
    v_generated := input -> 'generated';
    v_id := v_generated ->> 'id';
    v_session := v_generated ->> 'session';
    IF jsonb_typeof(v_generated) IS DISTINCT FROM 'object'
        OR jsonb_typeof(v_generated -> 'id') IS DISTINCT FROM 'string' OR v_id !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'
        OR jsonb_typeof(v_generated -> 'session') IS DISTINCT FROM 'string' OR v_session !~ '^[A-Za-z0-9_-]{43}$'
        OR jsonb_typeof(v_generated -> 'sessionHash') IS DISTINCT FROM 'string' OR (v_generated ->> 'sessionHash') !~ '^[a-f0-9]{64}$'
        OR jsonb_typeof(v_generated -> 'previewToken') IS DISTINCT FROM 'string' OR (v_generated ->> 'previewToken') !~ '^[A-Za-z0-9_-]{43}$' THEN
      RETURN jsonb_build_object('status', 400, 'body', jsonb_build_object('error', '项目凭据格式无效。'));
    END IF;
    -- A missing usage row is also serialized by the unique day key.
    INSERT INTO public.ludoready_usage AS usage (day, count) VALUES (v_day, 1)
      ON CONFLICT (day) DO UPDATE SET count = usage.count + 1 WHERE usage.count < 20
      RETURNING count INTO v_count;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('status', 429, 'body', jsonb_build_object('error', '今天的制作名额已满，请明天再试。每次修改也会使用一个制作名额。'));
    END IF;
    v_job := jsonb_build_object(
      'id', v_id, 'prompt', v_prompt, 'status', 'queued', 'stage', '准备制作', 'error', NULL,
      'events', jsonb_build_array(jsonb_build_object('time', v_time, 'stage', '准备制作', 'message', '项目已创建，正在等待制作。', 'revision', 0)),
      'createdAt', v_time, 'sessionHash', v_generated ->> 'sessionHash', 'previewToken', v_generated ->> 'previewToken',
      'revision', 0, 'changePrompt', NULL, 'revisions', '[]'::jsonb, 'hasPublished', false, 'publishedRevision', NULL,
      'publication', NULL, 'runId', NULL, 'runStartedAt', NULL, 'attemptStartedAt', v_time);
    INSERT INTO public.ludoready_projects (id, job) VALUES (v_id, v_job);
    RETURN jsonb_build_object('status', 200, 'body', jsonb_build_object('job', v_job, 'session', v_session));
  END IF;

  IF op IN ('claim', 'claim-next') THEN
    -- The whole site has one worker slot. Timer invocations and the historical
    -- owner-authorized claim share this transaction lock; a running job keeps
    -- the slot occupied after the claiming transaction has committed.
    PERFORM pg_advisory_xact_lock(774162183);
    FOR v_id IN SELECT project.id FROM public.ludoready_projects AS project
      WHERE project.job ->> 'status' = 'running'
        AND v_now - COALESCE(project.job ->> 'runStartedAt', project.job ->> 'attemptStartedAt', project.job ->> 'createdAt')::timestamptz > interval '31 minutes'
      FOR UPDATE LOOP
      -- Reuse the existing expiry transition, including revision/event updates
      -- and preservation of published games and private drafts.
      PERFORM public.ludoready_state('get', jsonb_build_object('id', v_id));
    END LOOP;
    IF op = 'claim-next' THEN
      IF EXISTS (SELECT 1 FROM public.ludoready_projects WHERE job ->> 'status' = 'running') THEN
        RETURN jsonb_build_object('status', 200, 'body', jsonb_build_object('claimed', false));
      END IF;
      SELECT project.id INTO v_id FROM public.ludoready_projects AS project
        WHERE project.job ->> 'status' = 'queued'
        ORDER BY COALESCE(project.job ->> 'attemptStartedAt', project.job ->> 'createdAt'), project.id
        LIMIT 1 FOR UPDATE SKIP LOCKED;
      IF NOT FOUND THEN
        RETURN jsonb_build_object('status', 200, 'body', jsonb_build_object('claimed', false));
      END IF;
    ELSE
      v_id := input ->> 'id';
    END IF;
  END IF;

  -- Serialize claims, revisions, callbacks and timeout transitions on one job.
  SELECT project.job INTO v_job FROM public.ludoready_projects AS project WHERE project.id = v_id FOR UPDATE;
  IF v_job IS NOT NULL THEN
    v_revision := COALESCE((v_job ->> 'revision')::integer, 0);
    v_revisions := COALESCE(NULLIF(v_job -> 'revisions', 'null'::jsonb), '[]'::jsonb);
    v_has_published := COALESCE((v_job ->> 'hasPublished')::boolean, v_job ->> 'status' = 'complete');
    v_job := v_job || jsonb_build_object('revision', v_revision, 'revisions', v_revisions,
      'changePrompt', COALESCE(v_job -> 'changePrompt', 'null'::jsonb), 'hasPublished', v_has_published,
      'publishedRevision', COALESCE(NULLIF(v_job -> 'publishedRevision', 'null'::jsonb), CASE WHEN v_has_published THEN '0'::jsonb ELSE 'null'::jsonb END),
      'publication', COALESCE(v_job -> 'publication', 'null'::jsonb));
    v_started := COALESCE(v_job ->> 'runStartedAt', v_job ->> 'attemptStartedAt', v_job ->> 'createdAt')::timestamptz;
    IF v_job ->> 'status' = 'running' AND v_now - v_started > interval '31 minutes' THEN
      v_message := '本次制作等待时间过长，已停止。项目已保留，请补充要求继续修改。';
      SELECT ordinality::integer - 1 INTO v_revision_index FROM jsonb_array_elements(v_revisions) WITH ORDINALITY
        WHERE (value ->> 'revision')::integer = v_revision LIMIT 1;
      IF v_revision_index IS NOT NULL THEN
        v_revisions := jsonb_set(v_revisions, ARRAY[v_revision_index::text, 'status'], '"failed"'::jsonb);
      END IF;
      v_events := COALESCE(v_job -> 'events', '[]'::jsonb) || jsonb_build_array(jsonb_build_object('time', v_time, 'stage', '制作中断', 'message', v_message, 'revision', v_revision));
      SELECT COALESCE(jsonb_agg(value ORDER BY ordinality), '[]'::jsonb) INTO v_events
        FROM jsonb_array_elements(v_events) WITH ORDINALITY WHERE ordinality > GREATEST(jsonb_array_length(v_events) - 60, 0);
      v_job := v_job || jsonb_build_object('status', 'failed', 'stage', '制作中断', 'error', v_message,
        'revisions', v_revisions, 'events', v_events, 'runId', NULL, 'runStartedAt', NULL);
      UPDATE public.ludoready_projects SET job = v_job WHERE id = v_id;
      -- Later rejection uses RETURN, not RAISE: the timeout remains committed.
    END IF;
  END IF;

  IF op = 'get' THEN
    RETURN jsonb_build_object('status', 200, 'body', jsonb_build_object('job', v_job));
  ELSIF op = 'authorized' THEN
    RETURN jsonb_build_object('status', 200, 'body', jsonb_build_object('job',
      CASE WHEN jsonb_typeof(input -> 'sessionHash') = 'string' AND input ->> 'sessionHash' = v_job ->> 'sessionHash' THEN v_job ELSE NULL END));
  ELSIF op = 'preview' THEN
    RETURN jsonb_build_object('status', 200, 'body', jsonb_build_object('job',
      CASE WHEN (v_job ->> 'hasPublished')::boolean AND jsonb_typeof(input -> 'token') = 'string' AND input ->> 'token' = v_job ->> 'previewToken' THEN v_job ELSE NULL END));
  END IF;
  IF v_job IS NULL OR (op IN ('revise', 'claim') AND
      (jsonb_typeof(input -> 'sessionHash') IS DISTINCT FROM 'string' OR (input ->> 'sessionHash') IS DISTINCT FROM (v_job ->> 'sessionHash'))) THEN
    RETURN jsonb_build_object('status', 404, 'body', jsonb_build_object('error', '找不到这个项目，请在原浏览器中打开。'));
  END IF;

  IF op = 'revise' THEN
    IF v_job ->> 'status' IN ('queued', 'running') THEN
      RETURN jsonb_build_object('status', 409, 'body', jsonb_build_object('error', '这个项目正在制作，请等待当前制作结束。'));
    END IF;
    INSERT INTO public.ludoready_usage AS usage (day, count) VALUES (v_day, 1)
      ON CONFLICT (day) DO UPDATE SET count = usage.count + 1 WHERE usage.count < 20
      RETURNING count INTO v_count;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('status', 429, 'body', jsonb_build_object('error', '今天的制作名额已满，请明天再试。每次修改也会使用一个制作名额。'));
    END IF;
    v_revision := v_revision + 1;
    v_revisions := v_job -> 'revisions' || jsonb_build_array(jsonb_build_object('revision', v_revision, 'prompt', v_prompt, 'time', v_time, 'status', 'queued'));
    v_job := v_job || jsonb_build_object('revision', v_revision, 'changePrompt', v_prompt, 'revisions', v_revisions,
      'runId', NULL, 'runStartedAt', NULL, 'attemptStartedAt', v_time);
    v_status := 'queued'; v_stage := '准备制作'; v_message := '已收到第 ' || v_revision || ' 次修改：' || v_prompt; v_error := 'null'::jsonb;
  ELSIF op IN ('claim', 'claim-next') THEN
    IF v_job ->> 'status' <> 'queued' OR (op = 'claim' AND v_revision <> v_requested_revision)
        OR EXISTS (SELECT 1 FROM public.ludoready_projects WHERE job ->> 'status' = 'running') THEN
      RETURN jsonb_build_object('status', 200, 'body', jsonb_build_object('claimed', false));
    END IF;
    v_job := v_job || jsonb_build_object('runId', input ->> 'runId', 'runStartedAt', v_time);
    v_status := 'running'; v_stage := '准备制作';
    v_message := CASE WHEN v_revision > 0 THEN '已开始根据修改要求继续制作。' ELSE '已开始制作你的 2D 网页游戏。' END;
    v_error := 'null'::jsonb;
  ELSE
    IF v_job ->> 'status' <> 'running' OR v_revision <> v_requested_revision OR (v_job ->> 'runId') IS DISTINCT FROM (input ->> 'runId') THEN
      RETURN jsonb_build_object('status', 409, 'body', jsonb_build_object('error', '制作任务已经结束或被新的修改替代。'));
    END IF;
    v_status := input ->> 'status'; v_stage := input ->> 'stage'; v_message := input ->> 'message'; v_error := COALESCE(input -> 'error', 'null'::jsonb);
    IF input ? 'draftSourceKey' THEN
      v_job := v_job || jsonb_build_object('draftSourceKey', input ->> 'draftSourceKey');
    END IF;
    IF v_status = 'complete' THEN
      v_job := v_job || jsonb_build_object('hasPublished', true, 'publishedRevision', v_revision, 'publication', v_publication);
      v_job := v_job - 'draftSourceKey';
    END IF;
    IF v_status <> 'running' THEN
      v_job := v_job || jsonb_build_object('runId', NULL, 'runStartedAt', NULL);
    END IF;
  END IF;

  v_revisions := v_job -> 'revisions';
  SELECT ordinality::integer - 1 INTO v_revision_index FROM jsonb_array_elements(v_revisions) WITH ORDINALITY
    WHERE (value ->> 'revision')::integer = v_revision LIMIT 1;
  IF v_revision_index IS NOT NULL THEN
    v_revisions := jsonb_set(v_revisions, ARRAY[v_revision_index::text, 'status'], to_jsonb(v_status));
  END IF;
  v_events := COALESCE(v_job -> 'events', '[]'::jsonb) || jsonb_build_array(jsonb_build_object('time', v_time, 'stage', v_stage, 'message', v_message, 'revision', v_revision));
  SELECT COALESCE(jsonb_agg(value ORDER BY ordinality), '[]'::jsonb) INTO v_events
    FROM jsonb_array_elements(v_events) WITH ORDINALITY WHERE ordinality > GREATEST(jsonb_array_length(v_events) - 60, 0);
  v_job := v_job || jsonb_build_object('status', v_status, 'stage', v_stage, 'error', v_error, 'revisions', v_revisions, 'events', v_events);
  UPDATE public.ludoready_projects SET job = v_job WHERE id = v_id;
  IF op IN ('claim', 'claim-next') THEN
    RETURN jsonb_build_object('status', 200, 'body', jsonb_build_object('claimed', true, 'job', v_job));
  ELSIF op = 'revise' THEN
    RETURN jsonb_build_object('status', 200, 'body', jsonb_build_object('job', v_job));
  END IF;
  RETURN jsonb_build_object('status', 200, 'body', jsonb_build_object('ok', true, 'job', v_job));
EXCEPTION WHEN OTHERS THEN
  -- Roll back this invocation's writes and keep database details out of HTTP errors.
  RETURN jsonb_build_object('status', 500, 'body', jsonb_build_object('error', '项目状态服务暂时不可用，请稍后重试。'));
END;
$ludoready$;

REVOKE ALL ON FUNCTION public.ludoready_state(text, jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.ludoready_state(text, jsonb) TO service_role;

COMMIT;
